// Valida lo que manda Armoni y lo deja listo para Notion
const TOKEN = 'mercado-7d41c2a9e05b';
const CAT_GASTO = ['Alimentación', 'Salidas', 'Salidas Ema', 'Hogar', 'Carro', 'Hijo', 'Salud', 'Tarjetas', 'Ahorro', 'Otros'];   // Servicios se registra solo
const CAT_INGRESO = ['Hogar', 'Alimentación', 'Salidas', 'Ahorro', 'Otros'];   // Ahorro como ingreso = plata que se sacó del ahorro
const AUTOMATICOS = /arriendo|jard[ií]n|cuota\s+(del\s+)?(carro|cr[eé]dito)/i;

let b = $input.first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};

const falla = (error) => [{ json: { ok: false, error } }];

if (b.token !== TOKEN) return falla('token');
// registros que esperaron sin conexión: cada uno trae un código; si ya llegó antes, no se guarda dos veces
const colaId = String(b.colaId || '').slice(0, 40);
if (colaId) {
  const sd = $getWorkflowStaticData('global'); sd.cola = sd.cola || {};
  // el código solo cuenta como «ya guardado» cuando el flujo TERMINÓ bien (nodo «Confirmar cola»).
  // Si Notion falló, el nodo «Quitar de cola» lo borra y el reintento vuelve a intentarlo; un número (formato de antes) = guardado.
  const prev = sd.cola[colaId];
  if (prev && (typeof prev === 'number' || prev.ok || Date.now() - prev.t < 45000)) return falla('repetido');
  sd.cola[colaId] = { t: Date.now(), ok: false };
  const ks = Object.keys(sd.cola); if (ks.length > 2000) ks.slice(0, ks.length - 2000).forEach(k => delete sd.cola[k]);
}
const tipo = String(b.tipo || '');
if (tipo !== 'Gasto' && tipo !== 'Ingreso') return falla('tipo');
const concepto = String(b.concepto || '').trim().slice(0, 80);
const categoria = String(b.categoria || '');
const fecha = String(b.fecha || '');
const monto = Math.round(Number(b.monto));
const notas = String(b.nota || b.notas || '').trim().slice(0, 300);
const lugar = String(b.lugar || '').trim().slice(0, 80);
const lugarId = /^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i.test(String(b.lugarId || '').trim()) ? String(b.lugarId).trim() : '';   // lugar que ya existe en Restaurantes: no se busca ni se crea
const punt = Number(b.puntuacion);
const puntuacion = punt >= 1 && punt <= 10 ? Math.round(punt * 2) / 2 : null;
const comentario = String(b.comentario || '').trim().slice(0, 200);
// cuántos comieron (solo salidas con lugar): entero de 1 a 30
const pers = Math.round(Number(b.personas));
const personas = pers >= 1 && pers <= 30 ? pers : null;
// Salidas Ema: si se pagó otro día (boletas compradas antes), el día en que salieron
// «Salida»: a qué salida pertenece (la categoría dice en qué se fue la plata; esto dice con quién fue)
const salida = ['Con Ema', 'Pareja'].includes(b.salida) ? b.salida : (categoria === 'Salidas Ema' ? 'Con Ema' : '');
let fechaSalida = String(b.fechaSalida || '');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaSalida) || fechaSalida === String(b.fecha || '') || salida !== 'Con Ema') fechaSalida = '';

// «medio»: cómo se pagó. Lo pagado en EFECTIVO no es plata de la cuenta: se guarda con Monto 0 y el valor en «Efectivo»,
// así no baja el bolsillo para gastar, ni sale en Tu mes ni en Balance, pero sí en la salida con Ema. Sin «medio» = digital (lo de siempre).
const medio = String(b.medio || '').toLowerCase() === 'efectivo' && tipo === 'Gasto' ? 'efectivo' : 'digital';

if (!concepto) return falla('concepto');
if (!(tipo === 'Gasto' ? CAT_GASTO : CAT_INGRESO).includes(categoria)) return falla('categoria');
if (tipo === 'Gasto' && AUTOMATICOS.test(concepto)) return falla('Eso ya se registra solo desde su aviso');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) return falla('fecha');
if (!(monto > 0) || monto > 1000000000) return falla('monto');

return [{ json: { ok: true, colaId, tipo, concepto, categoria, fecha, monto, notas, lugar, lugarId, puntuacion, comentario, personas, fechaSalida, salida, medio, forzar: !!b.forzar } }];

// Lee una propiedad venga como página completa de Notion (properties) o simplificada de n8n (property_xxx)
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : (pr.status ? pr.status.name : null);
    if (tipo === 'relacion') return pr.relation && pr.relation[0] ? pr.relation[0].id : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'relacion') { const r = Array.isArray(v) ? v[0] : v; return r ? (typeof r === 'object' ? r.id : String(r)) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};

const v = $('Validar movimiento').first().json;
const lugs = $input.all().map(i => i.json).filter(x => x && x.id);
const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().split(' ').map(w => w.replace(/s$/, '')).join(' ');
const buscado = norm(v.lugar);
// ¿es un sitio para comer? → «Restaurante» (sale en Restaurantes). Un parque, un centro comercial o un juego es «Plan Ema».
const COMIDA = /helad|paleter|restaur|pizz|burger|hamburg|sushi|asadero|caf[eé]\b|cafeter|crepe|panader|parrilla|bistr|pasteler|arepa|empanad|comidas?\b|postre|wok|brasa|sandwich|fritanga|yogur|waffle|batido/i;
const PLAN = /parque|\bcc\b|c\.c\.|centro comercial|mall|plaza|zool|granja|cine|piscina|acu[aá]tic|ecoparque|bosque|bot[aá]nic|museo|pance|r[ií]o\b|finca|hacienda|lago|playa|ludoteca|juegos|arkadia|salto|inflable|trampol/i;
const esComida = COMIDA.test(v.lugar) || (v.categoria === 'Salidas' && !PLAN.test(v.lugar));
// primero el nombre exacto; si no, que uno contenga al otro como palabras completas (así «Pan» no se confunde con «Pandebono»)
const conPalabras = (a, b) => (' ' + a + ' ').includes(' ' + b + ' ');
const nombres = lugs.map(l => ({ id: l.id, n: norm(leer(l, 'Nombre', 'titulo')) })).filter(x => x.n);
let lugarId = (nombres.find(x => x.n === buscado) || {}).id || null;
if (!lugarId && buscado.length > 3) {
  const m = nombres.find(x => x.n.length > 3 && (conPalabras(x.n, buscado) || conPalabras(buscado, x.n)));
  if (m) lugarId = m.id;
}
// un lugar que este flujo creó hace poco y que Notion todavía no muestra en la búsqueda (gastos en cola que llegan seguidos)
if (!lugarId) { const sd = $getWorkflowStaticData('global'); const r = (sd.lugaresNuevos || {})[buscado]; if (r && Date.now() - r.t < 30 * 60000) lugarId = r.id; }
return [{ json: { lugarId, crear: !lugarId, esEma: (v.salida === 'Con Ema' || v.categoria === 'Salidas Ema') && !esComida, nombre: v.lugar, puntuacion: v.puntuacion, tienePuntuacion: v.puntuacion != null, comentario: v.comentario || '' } }];

const v = $('Validar movimiento').first().json;
let lugarId = v.lugarId || null;
let creado = false;
for (const n of ['Crear lugar con puntuación', 'Crear lugar sin puntuación', 'Crear restaurante con puntuación', 'Crear restaurante sin puntuación']) {
  try { const c = $(n).first(); if (c && c.json && c.json.id) { lugarId = c.json.id; creado = true; break; } } catch (e) {}
}
// se recuerda 30 min: si llega otro gasto del mismo lugar antes de que Notion lo indexe, no se crea dos veces
if (creado) {
  const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().split(' ').map(w => w.replace(/s$/, '')).join(' ');
  const sd = $getWorkflowStaticData('global'); sd.lugaresNuevos = sd.lugaresNuevos || {};
  for (const [k, r] of Object.entries(sd.lugaresNuevos)) if (Date.now() - r.t > 30 * 60000) delete sd.lugaresNuevos[k];
  sd.lugaresNuevos[norm(v.lugar)] = { id: lugarId, t: Date.now() };
}
if (!lugarId) { try { const d = $('Decidir lugar').first(); if (d && d.json && d.json.lugarId) lugarId = d.json.lugarId; } catch (e) {} }
const esEfectivo = v.medio === 'efectivo';
// respaldo (si en Notion falta la columna «Efectivo»): Monto 0 y el valor en la nota, que salidas-ema sabe leer
const miles = String(v.monto).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const notasRespaldo = ('Pagado en efectivo $' + miles + ': no sale de la cuenta' + (v.notas ? ' · ' + v.notas : '')).slice(0, 300);
// efectivo: Monto queda en 0 (no toca ninguna suma de la cuenta) y el valor va en «Efectivo»
return [{ json: { concepto: v.concepto, monto: v.monto, tipo: v.tipo, categoria: v.categoria, fecha: v.fecha,
  notas: esEfectivo ? ('Pagado en efectivo: no sale de la cuenta' + (v.notas ? ' · ' + v.notas : '')).slice(0, 300) : (v.notas || ''),
  medio: esEfectivo ? 'efectivo' : 'digital', esEfectivo, notasRespaldo, efectivo: esEfectivo ? v.monto : 0,
  personas: v.personas != null ? v.personas : (v.categoria === 'Salidas Ema' ? 0 : null), lugarId, tieneLugar: !!lugarId, fechaSalida: v.fechaSalida || '', salida: v.salida || '' } }];

// Lee una propiedad venga como página completa de Notion (properties) o simplificada de n8n (property_xxx)
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : (pr.status ? pr.status.name : null);
    if (tipo === 'relacion') return pr.relation && pr.relation[0] ? pr.relation[0].id : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'relacion') { const r = Array.isArray(v) ? v[0] : v; return r ? (typeof r === 'object' ? r.id : String(r)) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};

// ¿Ese pago ya estaba anotado? (mismo tipo, casi el mismo valor y fechas cercanas: por ejemplo, llegó solo desde el correo de PSE)
const v = $('Validar movimiento').first().json;
if (v.forzar || v.medio === 'efectivo') return [{ json: { repetido: false } }];   // el efectivo nunca llega por PSE: no se compara
const dia = f => new Date(f + 'T12:00:00').getTime();
const cerca = $input.all().map(i => i.json).filter(x => x && x.id).map(x => ({
  concepto: leer(x, 'Concepto', 'titulo') || '', monto: leer(x, 'Monto', 'numero') || 0, tipo: leer(x, 'Tipo', 'select') || '',
  fecha: leer(x, 'Fecha', 'fecha') || '', categoria: leer(x, 'Categoría', 'select') || '', notas: leer(x, 'Notas', 'texto') || ''
})).filter(x => x.tipo === v.tipo && x.fecha && Math.abs(x.monto - v.monto) <= Math.max(100, v.monto * 0.005) && Math.abs(dia(x.fecha) - dia(v.fecha)) <= 4 * 864e5);
if (!cerca.length) return [{ json: { repetido: false } }];
const x = cerca.sort((a, b) => Math.abs(dia(a.fecha) - dia(v.fecha)) - Math.abs(dia(b.fecha) - dia(v.fecha)))[0];
const automatico = /pse|correo|gmail|autom|bancolombia|nequi|nu\b/i.test(x.notas + ' ' + x.concepto);
return [{ json: { repetido: true, parecido: { concepto: x.concepto, monto: x.monto, fecha: x.fecha, categoria: x.categoria, automatico } } }];

// Algo falló al guardar en Notion: se libera el código del registro (para que el reintento sí lo intente)
// y se arma una respuesta clara. Si Notion dice que falta una columna, se devuelve su nombre.
const v = $('Validar movimiento').first().json;
const e = $input.first().json || {};
if (v.colaId) { const sd = $getWorkflowStaticData('global'); if (sd.cola) delete sd.cola[v.colaId]; }
const txt = JSON.stringify(e);
const m = txt.match(/([^"\\.,:{}\[\]]{1,60}?) is not a property that exists/i);
const columna = m ? m[1].trim() : '';
const detalle = String((e.error && e.error.message) || e.error || e.message || '').slice(0, 200);
return [{ json: columna ? { ok: false, error: 'sin-columna', columna, detalle } : { ok: false, error: 'notion', detalle } }];

// Terminó bien: ahora sí el código del registro cuenta como guardado (un reenvío responde «repetido»)
const v = $('Validar movimiento').first().json;
if (v.colaId) { const sd = $getWorkflowStaticData('global'); sd.cola = sd.cola || {}; sd.cola[v.colaId] = { t: Date.now(), ok: true }; }
let aviso = null;   // se usó el respaldo: en Notion falta la columna «Efectivo» (Número) en Movimientos
for (const n of ['Crear efectivo sin columna', 'Crear efectivo con lugar sin columna']) {
  try { const c = $(n).first(); if (c && c.json && c.json.id) aviso = 'efectivo-sin-columna'; } catch (e) {}
}
return [{ json: { aviso } }];
